<script setup>
import { $api } from '@/utils/api'

const loading = ref(false)
const sending = ref(false)
const error = ref('')
const notice = ref('')
const tab = ref('campaigns')
const data = ref({ campaigns: [], deliveries: [], members: [], sport_codes: [] })
const composeOpen = ref(false)
const form = reactive({ name: '', subject: '', body: '', audience_type: 'all', sport_code_id: null, member_ids: [], scheduled_at: '' })
const statusColor = status => ({ sent: 'success', failed: 'error', queued: 'info', pending: 'warning', scheduled: 'warning' }[status] || 'secondary')
const dateTime = value => value ? new Date(value).toLocaleString('en-ZA') : '—'

async function load() { loading.value = true; try { data.value = await $api('/communications') } catch (e) { error.value = e?.data?.message || 'Communications could not be loaded.' } finally { loading.value = false } }
function openCompose() { Object.assign(form, { name: '', subject: '', body: '', audience_type: 'all', sport_code_id: null, member_ids: [], scheduled_at: '' }); composeOpen.value = true }
async function send() { sending.value = true; error.value = ''; try { const body = { ...form, scheduled_at: form.scheduled_at ? new Date(form.scheduled_at).toISOString() : null }; await $api('/communications', { method: 'POST', body }); composeOpen.value = false; notice.value = body.scheduled_at && new Date(body.scheduled_at) > new Date() ? 'Email campaign scheduled.' : 'Email campaign queued.'; await load() } catch (e) { error.value = e?.data?.message || 'Campaign could not be created.' } finally { sending.value = false } }
async function retry(item) { try { await $api(`/communications/deliveries/${item.id}/retry`, { method: 'POST' }); notice.value = `Retry queued for ${item.recipient_email}.`; await load() } catch (e) { error.value = e?.data?.message || 'Delivery could not be retried.' } }
onMounted(load)
</script>

<template>
  <section><div class="d-flex flex-wrap align-center justify-space-between gap-4 mb-6"><div><h1 class="text-h3">Communication Centre</h1><p class="text-medium-emphasis mb-0">Email announcements, automated member messages, delivery history and failures.</p></div><div class="d-flex gap-2"><VBtn variant="tonal" prepend-icon="tabler-refresh" @click="load">Refresh</VBtn><VBtn prepend-icon="tabler-mail-plus" @click="openCompose">New email</VBtn></div></div>
    <VAlert v-if="error" type="error" closable class="mb-4" @click:close="error=''">{{ error }}</VAlert><VAlert v-if="notice" type="success" closable class="mb-4" @click:close="notice=''">{{ notice }}</VAlert>
    <VRow class="mb-4"><VCol cols="6" md="3"><VCard><VCardText><div class="text-h4">{{ data.campaigns.length }}</div><div>Campaigns</div></VCardText></VCard></VCol><VCol cols="6" md="3"><VCard><VCardText><div class="text-h4 text-success">{{ data.deliveries.filter(d=>d.status==='sent').length }}</div><div>Recently sent</div></VCardText></VCard></VCol><VCol cols="6" md="3"><VCard><VCardText><div class="text-h4 text-info">{{ data.deliveries.filter(d=>['queued','pending'].includes(d.status)).length }}</div><div>Queued</div></VCardText></VCard></VCol><VCol cols="6" md="3"><VCard><VCardText><div class="text-h4 text-error">{{ data.deliveries.filter(d=>d.status==='failed').length }}</div><div>Failed</div></VCardText></VCard></VCol></VRow>
    <VTabs v-model="tab" class="mb-4"><VTab value="campaigns">Campaigns</VTab><VTab value="deliveries">Delivery log</VTab></VTabs><VWindow v-model="tab"><VWindowItem value="campaigns"><VCard><VDataTable :loading="loading" :items="data.campaigns" :headers="[{title:'Campaign',key:'name'},{title:'Type',key:'type'},{title:'Audience',key:'audience_type'},{title:'Recipients',key:'deliveries_count'},{title:'Sent',key:'sent_count'},{title:'Failed',key:'failed_count'},{title:'Status',key:'status'},{title:'Created',key:'created_at'}]"><template #item.name="{item}"><strong>{{ item.name }}</strong><div class="text-caption">{{ item.subject }}</div></template><template #item.status="{item}"><VChip size="small" :color="statusColor(item.status)" variant="tonal">{{ item.status }}</VChip></template><template #item.created_at="{item}">{{ dateTime(item.created_at) }}</template></VDataTable></VCard></VWindowItem><VWindowItem value="deliveries"><VCard><VDataTable :loading="loading" :items="data.deliveries" :headers="[{title:'Recipient',key:'recipient_email'},{title:'Message',key:'campaign.name'},{title:'Status',key:'status'},{title:'Attempts',key:'attempts'},{title:'Sent',key:'sent_at'},{title:'Failure',key:'failure_reason'},{title:'',key:'actions'}]"><template #item.recipient_email="{item}"><strong>{{ item.recipient_name }}</strong><div class="text-caption">{{ item.recipient_email }}</div></template><template #item.status="{item}"><VChip size="small" :color="statusColor(item.status)" variant="tonal">{{ item.status }}</VChip></template><template #item.sent_at="{item}">{{ dateTime(item.sent_at) }}</template><template #item.failure_reason="{item}"><span class="failure">{{ item.failure_reason || '—' }}</span></template><template #item.actions="{item}"><VBtn v-if="item.status==='failed'" size="small" variant="tonal" @click="retry(item)">Retry</VBtn></template></VDataTable></VCard></VWindowItem></VWindow>
    <VDialog v-model="composeOpen" max-width="800" persistent><VCard><VCardTitle class="pa-6">Compose member email</VCardTitle><VDivider/><VCardText class="pa-6"><VRow><VCol cols="12" md="6"><VTextField v-model="form.name" label="Internal campaign name" /></VCol><VCol cols="12" md="6"><VTextField v-model="form.subject" label="Email subject" /></VCol><VCol cols="12" md="6"><VSelect v-model="form.audience_type" :items="[{title:'All consenting members',value:'all'},{title:'One sport code',value:'sport_code'},{title:'Selected members',value:'selected'}]" label="Audience" /></VCol><VCol v-if="form.audience_type==='sport_code'" cols="12" md="6"><VSelect v-model="form.sport_code_id" :items="data.sport_codes" item-title="name" item-value="id" label="Sport code" /></VCol><VCol v-if="form.audience_type==='selected'" cols="12"><VSelect v-model="form.member_ids" :items="data.members" :item-title="m=>`${m.display_name || `${m.first_name} ${m.last_name}`} · ${m.member_number} · ${m.email}${m.email_consent?'':' (opted out)'}`" item-value="id" multiple chips label="Members" /></VCol><VCol cols="12"><VTextarea v-model="form.body" rows="9" label="Message" hint="Plain text is safely formatted into the email." persistent-hint /></VCol><VCol cols="12" md="6"><VTextField v-model="form.scheduled_at" type="datetime-local" label="Schedule (optional)" /></VCol></VRow><VAlert type="info" variant="tonal">Announcements are sent only to active members who consented to email. Transactional booking messages remain automatic.</VAlert></VCardText><VCardActions class="pa-6"><VSpacer/><VBtn variant="text" :disabled="sending" @click="composeOpen=false">Cancel</VBtn><VBtn :loading="sending" :disabled="!form.name||!form.subject||!form.body" @click="send">{{ form.scheduled_at ? 'Schedule email' : 'Queue email' }}</VBtn></VCardActions></VCard></VDialog>
  </section>
</template>
<style scoped>.failure{display:block;max-width:320px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}</style>
